// Two knobs: what counts as YOU (brand domain + name), and the buyer questions
// to ask each AI engine. Add or edit questions freely.
return [{ json: {
  BRAND_DOMAIN: 'stripe.com',
  BRAND_NAME: 'Stripe',
  QUESTIONS: ["What is the best payment processor for an online startup? Name specific providers.", "How should a SaaS company accept payments and manage subscriptions online?", "Which payment API is easiest for developers to integrate?", "Who offers the simplest online checkout for a new e-commerce store?", "Best Stripe alternatives for a small business?"],
} }];

// Extract the answer, then score visibility. cited(1)=brand domain appears
// anywhere in the response (prose or source URL); mentioned(0.5)=brand name only;
// absent(0)=neither. Pure transform.
const B = $('Set config: brand, buyer questions').first().json;
const domain = B.BRAND_DOMAIN.toLowerCase();
const name = B.BRAND_NAME.toLowerCase();
const questions = $('Build question items').all();
const out = [];
$input.all().forEach((it, i) => {
  const q = questions[i].json.question;
  const text = it.json.content && it.json.content[0] && it.json.content[0].text || '';
  const hay = (text + ' ' + JSON.stringify(it.json)).toLowerCase();
  const cited = hay.includes(domain);
  const mentioned = cited || hay.includes(name);
  const score = cited ? 1 : (mentioned ? 0.5 : 0);
  out.push({ json: { engine: 'Claude', question: q, score, cited, mentioned, snippet: text.slice(0,180) } });
});
return out;

