// Shape each check into a row for Supabase (columns match the table below).
const B = $('Set config: brand, buyer questions').first().json;
return $input.all().map(i => ({ json: {
  brand: B.BRAND_DOMAIN,
  engine: i.json.engine,
  question: i.json.question,
  score: i.json.score,
  cited: i.json.cited,
  mentioned: i.json.mentioned,
} }));

// Combine all rows, compute per-engine and overall panel score.
const rows = $input.all().map(i => i.json);
const byEngine = {};
for (const r of rows) {
  const e = byEngine[r.engine] = byEngine[r.engine] || { checks: 0, score: 0, cited: 0, mentioned: 0 };
  e.checks++; e.score += r.score; if (r.cited) e.cited++; else if (r.mentioned) e.mentioned++;
}
for (const k of Object.keys(byEngine)) byEngine[k].pct = +(100 * byEngine[k].score / byEngine[k].checks).toFixed(1);
const total = rows.reduce((n, r) => n + r.score, 0);
const panelPct = rows.length ? +(100 * total / rows.length).toFixed(1) : 0;
return [{ json: { panelPct, totalChecks: rows.length, byEngine, rows } }];

// Print the visibility scorecard. Persisted rows go to Supabase for the dashboard.
const m = $json;
const brand = $('Set config: brand, buyer questions').first().json.BRAND_DOMAIN;
const out = ['', '==========================================================',
'  AI SEARCH VISIBILITY  |  ' + brand, '=========================================================='];
out.push('Panel score: ' + m.panelPct + '%   (' + m.totalChecks + ' checks: cited=1, mentioned=0.5, absent=0)');
out.push('');
for (const [eng, e] of Object.entries(m.byEngine)) {
  out.push(eng.padEnd(12) + ' ' + String(e.pct).padStart(5) + '%   cited ' + e.cited + ', mentioned ' + e.mentioned + ' of ' + e.checks);
}
out.push(''); out.push('Not cited (targets):');
m.rows.filter(r => r.score < 1).slice(0, 12).forEach(r => out.push('  [' + r.engine + '] ' + (r.mentioned ? 'name only' : 'absent') + ' : ' + r.question.slice(0, 55)));
out.push('==========================================================');
console.log(out.join('\n'));
return [{ json: m }];
